# ============================================================================
# SYMMETRY EXPANSION   (v2.0.35)
# ============================================================================
#
# Six places in this notebook expand the asymmetric unit into a neighbour list:
# the picture, the two packing gates, the bond list, the shift screen, the
# anion-centred sums and the coordination quality pass. Until 2.0.35 each did
# it slightly differently and none of them wrapped the image back into the
# cell, so where a CIF deposits a coordinate outside [0,1) - 65 of the 142
# local files do - the translation shell stopped surrounding the site and
# neighbours fell off the edge. ICSD 23164 lost three of six Os-O bonds at
# 1.94 A and reported CN 3 against a formal valence of 5, as a plain ACCEPT.
#
# Measured over those 142 CIFs and 598 sites, against an expansion opened up
# until the answer stopped moving, at a 4.2 A cutoff and at 5.0 A:
#
#     the expansion as it stood              523 / 598      468 / 598
#     coordinates wrapped BEFORE the op      431 / 598      324 / 598
#     the image wrapped AFTER the op         594 / 598      572 / 598
#     ... and the site wrapped with them     598 / 598      598 / 598
#
# Wrapping the input is not the fix - it moves the site but not its images.
# Wrapping the image alone is not the fix either: a site deposited at x = 1.288
# sits at the edge of what its own shell covers, so the site is wrapped with
# its images. Both halves are needed, which is why site_centre() exists.


def wrap_into_cell(frac):
    """Fractional coordinates translated into [0, 1).

    A lattice translation and nothing more, so no distance that was already
    found can change; only ones that were missing are recovered.

    The clamp is not decoration. Both `x % 1.0` and `x - floor(x)` return
    exactly 1.0 for a small negative x, because the true answer rounds up to
    the nearest double, and 1.0 is outside the half-open cell this promises.
    A NaN passes through as NaN: whether the coordinates are finite is a
    question for the parse gate, not for a translation.
    """
    out = []
    for x in frac:
        w = x - math.floor(x) if x == x and abs(x) != float('inf') else x
        out.append(0.0 if w >= 1.0 else w)
    return out


# Images either way. The corpus never needs more than 2: its smallest
# interplanar spacing is 4.775 A (ICSD 68375 and two others) and the widest
# search any caller asks for is 6.0 A. A cell needing 5 would have a spacing
# under 1.2 A, which is not a crystal structure, so this raises rather than
# quietly returning a block that does not cover what it was asked for.
IMAGE_RANGE_MAX = 4


def image_range(cell, rmax):
    """How many lattice translations either way cover a sphere of radius rmax.

    Sized from the smallest INTERPLANAR SPACING, not the smallest cell edge.
    In an oblique cell a long axis can have a short perpendicular spacing, and
    it is the perpendicular distance that bounds the sphere the images cover:
    for 5.38 x 7.58 x 5.33 at beta = 120 the spacings are 4.66, 6.56 and 5.33,
    all shorter than the edges. For an orthogonal cell the two are equal, which
    is every structure in this corpus, so no range in it changes.

    With the site and its images both inside the cell, n translations reach at
    least n spacings in every direction, which is what makes the cover
    provable rather than hopeful.
    """
    if not rmax or rmax <= 0:
        return 1
    r = cell.reciprocal()
    d = [1.0 / x for x in (r.a, r.b, r.c) if x and x > 0]
    if not d:
        return 1
    n = max(1, int(math.ceil(rmax / min(d))))
    if n > IMAGE_RANGE_MAX:
        raise ValueError(
            f'a {rmax} A search in a cell whose smallest interplanar spacing '
            f'is {min(d):.2f} A needs {n} images either way, past the '
            f'{IMAGE_RANGE_MAX} this notebook allows')
    return n


def site_centre(cell, site):
    """The site's own position, wrapped into the cell its images live in.

    Half of the fix. The images are wrapped, so the site must be too, or a
    site deposited outside the cell measures its neighbours from a corner of
    the block instead of the middle of it.
    """
    return cell.orthogonalize(gemmi.Fractional(*wrap_into_cell(
        [site.fract.x, site.fract.y, site.fract.z])))


